const hash=s=>{let a=2166136261,b=5381;for(const c of String(s)){a=Math.imul(a^c.charCodeAt(0),16777619);b=Math.imul(b,33)^c.charCodeAt(0);}return (a>>>0).toString(16).padStart(8,'0')+(b>>>0).toString(16).padStart(8,'0');};
const FREE=new Set(['gmail.com','yahoo.fr','yahoo.com','hotmail.fr','hotmail.com','outlook.fr','outlook.com','live.fr','orange.fr','wanadoo.fr','free.fr','sfr.fr','laposte.net','icloud.com','gmx.fr','neuf.fr','bbox.fr']);
const company=l=>{let d=String(l.site||l.domain||mail(l.email).split('@')[1]||'').toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0];return FREE.has(d)?mail(l.email):d||mail(l.email);};
const unpack=r=>{try{return JSON.parse(r.payload||'{}');}catch{return {};}};
const columns=['task_key','type','priority','source','owner','status','created_at','last_action','next_action','due_at','payload'];
const fields=r=>Object.fromEntries(columns.map(k=>[k,String(r[k]??'')]));
